<script setup>
import { computed,ref } from 'vue';import { studio,roles,sessionPath,dateLabel } from '../store.js';import Icon from '../components/Icon.vue';const role=ref('all'),status=ref('all');const states={ready:'待开始',in_progress:'进行中',paused:'已暂停',completed:'已完成'};const list=computed(()=>studio.state.value.sessions.filter(s=>(role.value==='all'||s.roleId===role.value)&&(status.value==='all'||(status.value==='active'?s.status!=='completed':s.status==='completed'))).sort((a,b)=>(b.completedAt||b.createdAt).localeCompare(a.completedAt||a.createdAt)));
</script>
<template><div class="page-heading"><div><p class="eyebrow">MY INTERVIEWS</p><h1>每一次认真练习，都在这里。</h1><p class="muted">继续未完成的面试，或回看之前的发现。</p></div><RouterLink to="/interviews/new" class="button primary">开始新面试 <Icon name="right"/></RouterLink></div><section class="card"><div class="filters"><label>岗位<select v-model="role"><option value="all">全部岗位</option><option v-for="r in roles" :key="r.id" :value="r.id">{{r.title}}</option></select></label><label>状态<select v-model="status"><option value="all">全部状态</option><option value="active">未完成</option><option value="completed">已完成</option></select></label><span class="muted">{{list.length}} 条记录</span></div><article v-for="s in list" :key="s.id" class="list-row"><div class="inline"><span class="role-icon"><Icon :name="roles.find(r=>r.id===s.roleId)?.icon"/></span><div><h3>{{s.roleName}} · {{s.focusTopic||s.level}}</h3><p class="muted small">{{dateLabel(s.createdAt)}} · {{states[s.status]}} · {{s.seeded?'预置示例':'本次演示'}} · {{s.answers.length}} 道回答</p></div></div><div class="inline"><strong v-if="s.report" class="record-score">{{s.report.overall}}<small>分</small></strong><RouterLink :to="sessionPath(s)" class="button secondary">{{s.report?'查看报告':s.status==='ready'?'查看方案':'继续面试'}} →</RouterLink></div></article><div v-if="!list.length" class="empty"><h2>还没有符合条件的记录</h2><p>调整筛选，或开始一次新的练习。</p></div></section></template>
